const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const monthShort = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const monthNumber = (name) => monthNames.indexOf(name) + 1;

function translateUiText(source) {
  const raw = source.trim();
  if (!raw) return source;
  let result = uiCopy[raw];
  if (!result) {
    let match = raw.match(/^(\d+) of 12 months ready$/);
    if (match) result = `${match[1]} / 12 个月已就绪`;
    match = raw.match(/^Photo (\d+)$/);
    if (match) result = `照片 ${match[1]}`;
    match = raw.match(/^Prototype photo assigned to ([A-Za-z]+)$/);
    if (match && monthNumber(match[1])) result = `分配给 ${monthNumber(match[1])} 月的原型照片`;
    match = raw.match(/^Photo (\d+), unassigned prototype photo$/);
    if (match) result = `照片 ${match[1]}，未分配的原型照片`;
    match = raw.match(/^([A-Za-z]+) 2027 calendar preview$/);
    if (match && monthNumber(match[1])) result = `2027 年 ${monthNumber(match[1])} 月日历预览`;
    match = raw.match(/^([A-Za-z]+) 2027$/);
    if (match && monthNumber(match[1])) result = `2027 年 ${monthNumber(match[1])} 月`;
    match = raw.match(/^([A-Za-z]+) proof$/);
    if (match && monthNumber(match[1])) result = `${monthNumber(match[1])} 月预览`;
    match = raw.match(/^([A-Za-z]+) · PNG$/);
    if (match && monthNumber(match[1])) result = `${monthNumber(match[1])} 月 · PNG`;
    match = raw.match(/^Download ([A-Za-z]+) PNG$/);
    if (match && monthNumber(match[1])) result = `下载 ${monthNumber(match[1])} 月 PNG`;
    match = raw.match(/^([A-Za-z]+) needs a photo$/);
    if (match && monthNumber(match[1])) result = `${monthNumber(match[1])} 月还缺少照片`;
    match = raw.match(/^Swap January and ([A-Za-z]+) photos\?$/);
    if (match && monthNumber(match[1])) result = `交换 1 月和 ${monthNumber(match[1])} 月的照片？`;
    match = raw.match(/^Replace ([A-Za-z]+)’s photo\?$/);
    if (match && monthNumber(match[1])) result = `替换 ${monthNumber(match[1])} 月的照片？`;
    match = raw.match(/^([A-Za-z]+) · (Ready|Missing Photo)$/);
    if (match && monthNumber(match[1])) result = `${monthNumber(match[1])} 月 · ${uiCopy[match[2]]}`;
    match = raw.match(/^(Edit|Fill|Remove from) ([A-Za-z]+)$/);
    if (match && monthNumber(match[2])) result = match[1] === "Edit" ? `编辑 ${monthNumber(match[2])} 月` : match[1] === "Fill" ? `为 ${monthNumber(match[2])} 月添加照片` : `从 ${monthNumber(match[2])} 月移除照片`;
    if (!result && monthNames.includes(raw)) result = `${monthNumber(raw)} 月`;
    if (!result && monthShort.includes(raw)) result = `${monthShort.indexOf(raw) + 1}月`;
  }
  return result ? source.replace(raw, result) : source;
}

function translateNode(root) {
  if (root.nodeType === Node.TEXT_NODE) {
    if (root.parentElement?.closest(".calendar-body, .mini-calendar, .font-sample")) return;
    const translated = translateUiText(root.nodeValue);
    if (translated !== root.nodeValue) root.nodeValue = translated;
    return;
  }
  if (root.nodeType !== Node.ELEMENT_NODE) return;
  if (root.matches(".calendar-body, .mini-calendar, .font-sample")) return;
  for (const attribute of ["aria-label", "alt", "title"]) {
    if (!root.hasAttribute(attribute)) continue;
    const value = root.getAttribute(attribute);
    const translated = translateUiText(value);
    if (translated !== value) root.setAttribute(attribute, translated);
  }
  for (const child of root.childNodes) translateNode(child);
}

translateNode(document.documentElement);
new MutationObserver((records) => {
  for (const record of records) {
    if (record.type === "characterData") translateNode(record.target);
    if (record.type === "attributes") translateNode(record.target);
    for (const node of record.addedNodes) translateNode(node);
  }
}).observe(document.documentElement, { childList: true, characterData: true, attributes: true, attributeFilter: ["aria-label", "alt", "title"], subtree: true });
